"""Persistent, stage-aware scheduling for staged MultiLang benchmark freezes.

The scheduler is deliberately execution-agnostic.  It validates and snapshots a
supported staged freeze, selects the next eligible slot, and records typed attempt outcomes.
Issue #24 owns launching a harness and turning its evidence into sealed outcomes.
"""
from __future__ import annotations

import copy
import contextlib
import fcntl
import json
import math
import os
import re
import tempfile
import uuid
from collections import Counter
from datetime import datetime, timezone
from functools import lru_cache
from pathlib import Path
from typing import Any, Mapping

from jsonschema import Draft202012Validator, FormatChecker

from agent_harness_evals.research_contract import digest
from agent_harness_evals.security import assert_safe_for_persistence
from agent_harness_evals.staged_contract import freeze_errors
from agent_harness_evals import claude_capacity

ROOT = Path(__file__).resolve().parents[1]
SCHEMA_VERSION = "stage-scheduler-state/1"
TERMINAL_OUTCOMES = {
    "result_recorded",
    "unsupported",
    "infrastructure_missing",
    "infrastructure_failed",
}
DIGEST_PATTERN = re.compile(r"sha256:[0-9a-f]{64}")
OBSERVATION_FIELDS = {
    "account_id",
    "observed_at",
    "valid_until",
    "remaining_workflows",
    "weekly_remaining_workflows",
    "conservative_capacity_workflows",
    "recovery_at",
    "weekly_recovery_at",
    "external_usage_workflows",
    "evidence_digest",
}
DEFERRAL_REASONS = {
    "missing_quota_telemetry",
    "quota_observation_lacks_evidence",
    "stale_quota_telemetry",
    "incomplete_quota_telemetry",
    "missing_conservative_capacity",
    "insufficient_whole_workflow_headroom",
    "account_parallelism_exhausted",
    "local_compute_parallelism_exhausted",
}


class SchedulerError(ValueError):
    """The persisted state or requested transition violates the frozen policy."""


def _timestamp(value: str | datetime) -> datetime:
    try:
        if isinstance(value, datetime):
            parsed = value
        else:
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (AttributeError, TypeError, ValueError) as exc:
        raise SchedulerError("scheduler timestamp is not a valid date-time") from exc
    if parsed.tzinfo is None:
        raise SchedulerError("scheduler timestamps must include a timezone")
    return parsed.astimezone(timezone.utc)


def _format_timestamp(value: str | datetime) -> str:
    return _timestamp(value).isoformat().replace("+00:00", "Z")


def _require_digest(value: str, name: str) -> None:
    if not isinstance(value, str) or DIGEST_PATTERN.fullmatch(value) is None:
        raise SchedulerError(f"{name} must be a canonical sha256 digest")


def _require_mutation_authorized(
    freeze: Mapping[str, Any], *, allow_fixture: bool
) -> None:
    if freeze["purpose"] != "freeze" and not allow_fixture:
        raise SchedulerError(
            "scheduler mutation requires purpose=freeze or explicit fixture mode"
        )


_FREEZE_ERROR_CACHE: dict[
    tuple[str, str | None, str | None, str | None, str | None], tuple[str, ...]
] = {}


def _validated_freeze_errors(
    freeze: Mapping[str, Any],
    stage_a_freeze: Mapping[str, Any] | None,
    trusted_stage_a_freeze_digest: str | None,
    trusted_stage_a_disposition_digest: str | None,
    trusted_stage_a_outcome_seal_digest: str | None,
) -> tuple[str, ...]:
    key = (
        digest(freeze),
        digest(stage_a_freeze) if stage_a_freeze is not None else None,
        trusted_stage_a_freeze_digest,
        trusted_stage_a_disposition_digest,
        trusted_stage_a_outcome_seal_digest,
    )
    if key not in _FREEZE_ERROR_CACHE:
        _FREEZE_ERROR_CACHE[key] = tuple(
            freeze_errors(
                dict(freeze),
                stage_a_freeze=(
                    dict(stage_a_freeze) if stage_a_freeze is not None else None
                ),
                trusted_stage_a_freeze_digest=trusted_stage_a_freeze_digest,
                trusted_stage_a_disposition_digest=trusted_stage_a_disposition_digest,
                trusted_stage_a_outcome_seal_digest=trusted_stage_a_outcome_seal_digest,
            )
        )
    return _FREEZE_ERROR_CACHE[key]


def _slot_identities(freeze: Mapping[str, Any]) -> list[tuple[dict, dict]]:
    schedule = freeze["schedule"]
    plans = freeze["outcome_slot_plan"]["slots"]
    if len(schedule) != len(plans):
        raise SchedulerError("schedule and outcome slot plan lengths differ")
    pairs = []
    for scheduled, planned in zip(schedule, plans, strict=True):
        if (
            scheduled["arm_id"] != planned["arm_id"]
            or scheduled["task_id"] != planned["task"]["id"]
        ):
            raise SchedulerError("schedule and outcome slot plan identities differ")
        pairs.append((scheduled, planned))
    return pairs


def _routing_identities(freeze: Mapping[str, Any]) -> list[dict]:
    """Expose the nonsecret credential class and route frozen for every role."""
    return [
        {
            "arm_id": arm["arm_id"],
            "role_id": role["role_id"],
            "account_id": role["account_id"],
            "provider": role["provider"],
            "authentication": role["authentication"],
            "endpoint": role["endpoint"],
            "requested_model": role["requested_model"],
            "resolved_model": role["resolved_model"],
        }
        for arm in freeze["arms"]
        for role in arm["roles"]
    ]


def _account_demands(freeze: Mapping[str, Any], arm_id: str) -> dict[str, int]:
    arm = next(arm for arm in freeze["arms"] if arm["arm_id"] == arm_id)
    demands: dict[str, int] = {}
    for role in arm["roles"]:
        account_id = role["account_id"]
        demands[account_id] = demands.get(account_id, 0) + 1
    numerical = freeze.get("numerical_policy")
    if numerical is not None:
        demands[numerical["research_account"]["account_id"]] = 1
    return demands


def _accounts(freeze):
    accounts = {a["account_id"]: a for a in freeze["limits"]["provider_accounts"]}
    if freeze.get("numerical_policy"):
        account = freeze["numerical_policy"]["research_account"]
        accounts[account["account_id"]] = account
    return accounts


def _claude_account(freeze):
    if not freeze.get("numerical_policy"):
        return None
    return next(a["roles"][0]["account_id"] for a in freeze["arms"]
                if a["arm_id"] == "claude-code-claude-opus-5")


def _owner_managed_capacity(freeze):
    policy = freeze.get("numerical_policy") or {}
    return (policy.get("schema_version") == "stage-a-numerical-policy/2"
            and policy.get("provider_capacity_mode") == "owner_managed")


def account_reservation_demand(
    freeze: Mapping[str, Any], arm_id: str, *, remaining_attempts: int
) -> dict[str, int]:
    """Aggregate every role and remaining retry by actual shared account."""
    if remaining_attempts < 1:
        raise SchedulerError("remaining attempts must be positive")
    return {
        account_id: roles * remaining_attempts
        for account_id, roles in _account_demands(freeze, arm_id).items()
    }


def _deferral_id(slot: Mapping[str, Any], deferral: Mapping[str, Any]) -> str:
    evidence = {
        key: deferral[key]
        for key in (
            "decision_id",
            "at",
            "attempt",
            "reasons",
            "quota_observations",
        )
    }
    return str(
        uuid.uuid5(
            uuid.NAMESPACE_URL,
            f"{slot['trial_id']}/deferral/{digest(evidence)}",
        )
    )


def _decision_id(
    state: Mapping[str, Any],
    *,
    event_number: int,
    at: str | datetime,
    next_actual_order: int,
) -> str:
    return str(
        uuid.uuid5(
            uuid.NAMESPACE_URL,
            f"{state['manifest_digest']}/decision/{event_number}/"
            f"{_format_timestamp(at)}/{next_actual_order}",
        )
    )


def new_state(
    freeze: Mapping[str, Any],
    *,
    created_at: str | datetime,
    allow_fixture: bool = False,
    stage_a_freeze: Mapping[str, Any] | None = None,
    trusted_stage_a_freeze_digest: str | None = None,
    trusted_stage_a_disposition_digest: str | None = None,
    trusted_stage_a_outcome_seal_digest: str | None = None,
) -> dict:
    """Create the immutable plan and empty runtime ledger for one exact freeze."""
    errors = _validated_freeze_errors(
        freeze,
        stage_a_freeze,
        trusted_stage_a_freeze_digest,
        trusted_stage_a_disposition_digest,
        trusted_stage_a_outcome_seal_digest,
    )
    if errors:
        raise SchedulerError(f"invalid staged freeze: {errors[0]}")
    _require_mutation_authorized(freeze, allow_fixture=allow_fixture)
    if freeze["purpose"] == "freeze" and _timestamp(created_at) >= _timestamp(
        freeze["cohort_window"]["end"]
    ):
        raise SchedulerError("cannot initialize after the finite cohort window")
    manifest_digest = digest(freeze)
    slots = []
    for planned_order, (scheduled, outcome_slot) in enumerate(
        _slot_identities(freeze), 1
    ):
        trial_name = f"{manifest_digest}/trial/{outcome_slot['slot_id']}"
        slots.append(
            {
                "slot_id": outcome_slot["slot_id"],
                "trial_id": str(uuid.uuid5(uuid.NAMESPACE_URL, trial_name)),
                "task_id": scheduled["task_id"],
                "repetition": scheduled["repetition"],
                "arm_id": scheduled["arm_id"],
                "planned_order": planned_order,
                "actual_order": None,
                "status": "pending",
                "attempts": [],
                "deferrals": [],
                "terminal": None,
            }
        )
    state = {
        "schema_version": SCHEMA_VERSION,
        "manifest_digest": manifest_digest,
        "manifest_purpose": freeze["purpose"],
        "stage": freeze["stage"],
        "cohort_id": freeze["cohort_id"],
        "corpus_digest": freeze["corpus"]["manifest_digest"],
        "arm_ids": [arm["arm_id"] for arm in freeze["arms"]],
        "schedule_digest": digest(freeze["schedule"]),
        "schedule_seed": freeze["limits"]["seed"],
        "source_policy_digest": digest(freeze["source_policy"]),
        "routing_identities": _routing_identities(freeze),
        "stage_a_trust_digest": trusted_stage_a_freeze_digest,
        "stage_a_disposition_trust_digest": trusted_stage_a_disposition_digest,
        "stage_a_outcome_seal_trust_digest": trusted_stage_a_outcome_seal_digest,
        "created_at": _format_timestamp(created_at),
        "updated_at": _format_timestamp(created_at),
        "next_actual_order": 1,
        "slots": slots,
        "reservations": [],
        "quota_observations": [],
        "events": [],
    }
    if freeze.get("numerical_policy"):
        state["schema_version"] = "stage-scheduler-state/2"
        state["claude_capacity"] = copy.deepcopy(freeze["numerical_policy"]["claude_qualification_ledger"])
    validate_state(
        state,
        freeze,
        stage_a_freeze=stage_a_freeze,
        trusted_stage_a_freeze_digest=trusted_stage_a_freeze_digest,
        trusted_stage_a_disposition_digest=trusted_stage_a_disposition_digest,
        trusted_stage_a_outcome_seal_digest=trusted_stage_a_outcome_seal_digest,
    )
    return state


@lru_cache(maxsize=2)
def _state_validator(version=SCHEMA_VERSION) -> Draft202012Validator:
    suffix = "v2" if version == "stage-scheduler-state/2" else "v1"
    schema = json.loads((ROOT / f"schemas/stage-scheduler-state-{suffix}.schema.json").read_text())
    return Draft202012Validator(schema, format_checker=FormatChecker())


def _schema_errors(state: Mapping[str, Any]) -> list[str]:
    return [
        error.message
        for error in _state_validator(state.get("schema_version")).iter_errors(state)
    ]


def validate_state(
    state: Mapping[str, Any],
    freeze: Mapping[str, Any],
    *,
    stage_a_freeze: Mapping[str, Any] | None = None,
    trusted_stage_a_freeze_digest: str | None = None,
    trusted_stage_a_disposition_digest: str | None = None,
    trusted_stage_a_outcome_seal_digest: str | None = None,
) -> None:
    """Reject corruption, cross-freeze resume, and impossible state histories."""
    errors = _validated_freeze_errors(
        freeze,
        stage_a_freeze,
        trusted_stage_a_freeze_digest,
        trusted_stage_a_disposition_digest,
        trusted_stage_a_outcome_seal_digest,
    )
    if errors:
        raise SchedulerError(f"invalid staged freeze: {errors[0]}")
    shape = _schema_errors(state)
    if shape:
        raise SchedulerError(f"invalid scheduler state: {shape[0]}")
    expected_version = "stage-scheduler-state/2" if freeze.get("numerical_policy") else SCHEMA_VERSION
    if state["schema_version"] != expected_version:
        raise SchedulerError("scheduler accounting version differs from the freeze")
    identities = {
        "manifest_digest": digest(freeze),
        "manifest_purpose": freeze["purpose"],
        "stage": freeze["stage"],
        "cohort_id": freeze["cohort_id"],
        "corpus_digest": freeze["corpus"]["manifest_digest"],
        "arm_ids": [arm["arm_id"] for arm in freeze["arms"]],
        "schedule_digest": digest(freeze["schedule"]),
        "schedule_seed": freeze["limits"]["seed"],
        "source_policy_digest": digest(freeze["source_policy"]),
        "routing_identities": _routing_identities(freeze),
        "stage_a_trust_digest": trusted_stage_a_freeze_digest,
        "stage_a_disposition_trust_digest": trusted_stage_a_disposition_digest,
        "stage_a_outcome_seal_trust_digest": trusted_stage_a_outcome_seal_digest,
    }
    for field, expected in identities.items():
        if state.get(field) != expected:
            raise SchedulerError(f"resume rejected: {field} differs from frozen manifest")
    pairs = _slot_identities(freeze)
    if len(state["slots"]) != len(pairs):
        raise SchedulerError("resume rejected: missing or extra scheduled slots")
    actual_orders: set[int] = set()
    active_leases: set[str] = set()
    known_leases: set[str] = set()
    attempts_by_lease: dict[str, tuple[dict, dict]] = {}
    deferrals_by_id: dict[str, tuple[dict, dict]] = {}
    declared_accounts = set(_accounts(freeze))
    for index, (slot, (scheduled, planned)) in enumerate(
        zip(state["slots"], pairs, strict=True), 1
    ):
        expected_trial = str(
            uuid.uuid5(
                uuid.NAMESPACE_URL,
                f"{digest(freeze)}/trial/{planned['slot_id']}",
            )
        )
        expected = (
            planned["slot_id"],
            expected_trial,
            scheduled["task_id"],
            scheduled["repetition"],
            scheduled["arm_id"],
            index,
        )
        actual = (
            slot["slot_id"],
            slot["trial_id"],
            slot["task_id"],
            slot["repetition"],
            slot["arm_id"],
            slot["planned_order"],
        )
        if actual != expected:
            raise SchedulerError("resume rejected: slot plan identity or order changed")
        if slot["actual_order"] is not None:
            if slot["actual_order"] in actual_orders:
                raise SchedulerError("duplicate actual dispatch order")
            actual_orders.add(slot["actual_order"])
        if slot["actual_order"] is None and slot["attempts"]:
            raise SchedulerError("attempted slot lacks actual dispatch order")
        if len(slot["attempts"]) > freeze["limits"]["attempts"]:
            raise SchedulerError("slot exceeds frozen attempt limit")
        for attempt_number, attempt in enumerate(slot["attempts"], 1):
            if attempt["attempt"] != attempt_number:
                raise SchedulerError("attempt lineage is not contiguous")
            expected_id = str(
                uuid.uuid5(
                    uuid.NAMESPACE_URL,
                    f"{slot['trial_id']}/attempt/{attempt_number}",
                )
            )
            if attempt["attempt_id"] != expected_id:
                raise SchedulerError("attempt identity differs from stable lineage")
            if attempt["lease_id"] in known_leases:
                raise SchedulerError("duplicate lease identity")
            known_leases.add(attempt["lease_id"])
            attempts_by_lease[attempt["lease_id"]] = (slot, attempt)
            expected_reservations = account_reservation_demand(
                freeze,
                slot["arm_id"],
                remaining_attempts=freeze["limits"]["attempts"] - attempt_number + 1,
            )
            if attempt["account_reservations"] != expected_reservations:
                raise SchedulerError("attempt reservation omits a role or retry")
            if attempt["finished_at"] is None:
                active_leases.add(attempt["lease_id"])
                if (
                    attempt["account_consumption"]
                    or attempt["outcome"] is not None
                    or attempt["error_code"] is not None
                    or attempt["evidence_digest"] is not None
                ):
                    raise SchedulerError("active attempt cannot claim terminal evidence")
            elif attempt["account_consumption"] != _account_demands(
                freeze, slot["arm_id"]
            ):
                raise SchedulerError("completed attempt consumption omits an actual role")
            elif attempt["outcome"] not in TERMINAL_OUTCOMES or attempt["evidence_digest"] is None:
                raise SchedulerError("completed attempt lacks typed retained evidence")
            elif attempt["outcome"] == "infrastructure_failed" and (
                not isinstance(attempt["error_code"], str)
                or not attempt["error_code"].strip()
            ):
                raise SchedulerError("infrastructure failure lacks a typed error code")
            elif attempt["outcome"] != "infrastructure_failed" and attempt["error_code"] is not None:
                raise SchedulerError("non-infrastructure outcome carries an error code")
            if attempt_number < len(slot["attempts"]):
                if (
                    attempt["outcome"] != "infrastructure_failed"
                    or attempt["error_code"]
                    not in freeze["limits"]["retry_policy"]["retryable_error_codes"]
                ):
                    raise SchedulerError("attempt follows a nonretryable outcome")
                if _timestamp(attempt["finished_at"]) > _timestamp(
                    slot["attempts"][attempt_number]["started_at"]
                ):
                    raise SchedulerError("retry starts before the prior attempt finished")
        if slot["status"] == "in_flight" and not slot["attempts"]:
            raise SchedulerError("in-flight slot has no attempt")
        if slot["status"] == "in_flight" and slot["attempts"][-1]["finished_at"] is not None:
            raise SchedulerError("in-flight slot has a finished current attempt")
        if slot["status"] != "in_flight" and slot["attempts"] and slot["attempts"][-1]["finished_at"] is None:
            raise SchedulerError("active attempt is not marked in-flight")
        if slot["status"] in {"terminal", "unstarted"} and slot["terminal"] is None:
            raise SchedulerError("reconciled slot lacks terminal disposition")
        if slot["status"] in {"pending", "in_flight"} and slot["terminal"] is not None:
            raise SchedulerError("open slot has a terminal disposition")
        if slot["status"] == "terminal":
            if not slot["attempts"]:
                raise SchedulerError("terminal slot has no final attempt")
            final = slot["attempts"][-1]
            expected_terminal = {
                "disposition": final["outcome"],
                "attempt": final["attempt"],
                "at": final["finished_at"],
                "evidence_digest": final["evidence_digest"],
            }
            if slot["terminal"] != expected_terminal:
                raise SchedulerError("terminal evidence differs from final attempt")
        if slot["status"] == "unstarted" and (
            slot["terminal"]["disposition"] != "unstarted"
            or not slot["terminal"].get("reason")
        ):
            raise SchedulerError("unstarted slot lacks its finite-stop reason")
        if slot["status"] == "pending" and slot["attempts"]:
            last = slot["attempts"][-1]
            if (
                last["outcome"] != "infrastructure_failed"
                or last["error_code"]
                not in freeze["limits"]["retry_policy"]["retryable_error_codes"]
                or len(slot["attempts"])
                >= freeze["limits"]["retry_policy"]["max_attempts"]
            ):
                raise SchedulerError("pending retry does not follow a retryable outcome")
        for deferral in slot["deferrals"]:
            if deferral["deferral_id"] in deferrals_by_id:
                raise SchedulerError("duplicate quota deferral identity")
            if deferral["deferral_id"] != _deferral_id(slot, deferral):
                raise SchedulerError("quota deferral identity differs from its evidence")
            if deferral["attempt"] > len(slot["attempts"]) + 1:
                raise SchedulerError("quota deferral references a future attempt")
            if _timestamp(deferral["at"]) < _timestamp(state["created_at"]):
                raise SchedulerError("quota deferral predates scheduler state")
            if any(
                reason["reason"] not in DEFERRAL_REASONS
                for reason in deferral["reasons"]
            ):
                raise SchedulerError("quota deferral contains an unknown reason")
            observed = _observation_map(deferral["quota_observations"])
            reason_accounts = {
                reason["account_id"]
                for reason in deferral["reasons"]
                if reason["account_id"] != "local-compute"
            }
            demand_accounts = set(
                account_reservation_demand(
                    freeze,
                    slot["arm_id"],
                    remaining_attempts=freeze["limits"]["attempts"]
                    - deferral["attempt"]
                    + 1,
                )
            )
            if (
                set(observed) - demand_accounts
                or reason_accounts - demand_accounts
                or reason_accounts - declared_accounts
            ):
                raise SchedulerError("quota deferral evidence references the wrong account")
            deferrals_by_id[deferral["deferral_id"]] = (slot, deferral)
    blocks: list[list[dict]] = []
    for slot in state["slots"]:
        identity = (slot["task_id"], slot["repetition"])
        if not blocks or (
            blocks[-1][0]["task_id"], blocks[-1][0]["repetition"]
        ) != identity:
            blocks.append([])
        blocks[-1].append(slot)
    for previous, current in zip(blocks, blocks[1:]):
        started = [slot for slot in current if slot["attempts"]]
        if not started:
            continue
        if any(slot["status"] != "terminal" for slot in previous):
            raise SchedulerError("later block starts before the prior block is terminal")
        previous_finished = max(
            _timestamp(slot["terminal"]["at"]) for slot in previous
        )
        current_started = min(
            _timestamp(slot["attempts"][0]["started_at"]) for slot in started
        )
        if previous_finished > current_started:
            raise SchedulerError("later block starts before the prior block finished")
        if max(slot["actual_order"] for slot in previous) >= min(
            slot["actual_order"] for slot in started
        ):
            raise SchedulerError("actual dispatch order crosses block boundaries")
    reservation_leases = {item["lease_id"] for item in state["reservations"]}
    if (
        len(reservation_leases) != len(state["reservations"])
        or reservation_leases != active_leases
    ):
        raise SchedulerError("active attempts and account reservations differ")
    for reservation in state["reservations"]:
        slot, attempt = attempts_by_lease[reservation["lease_id"]]
        expected_reservation = {
            "lease_id": attempt["lease_id"],
            "slot_id": slot["slot_id"],
            "attempt": attempt["attempt"],
            "created_at": attempt["started_at"],
            "accounts": attempt["account_reservations"],
        }
        if reservation != expected_reservation:
            raise SchedulerError("reservation ledger differs from active attempt")
    if actual_orders and actual_orders != set(range(1, max(actual_orders) + 1)):
        raise SchedulerError("actual dispatch order is not contiguous")
    if state["next_actual_order"] != len(actual_orders) + 1:
        raise SchedulerError("next actual order disagrees with dispatch history")
    dispatch_events = [
        event["lease_id"] for event in state["events"] if event["type"] == "dispatch"
    ]
    finish_events = [
        event["lease_id"]
        for event in state["events"]
        if event["type"] == "attempt_finished"
    ]
    finished_leases = {
        attempt["lease_id"]
        for slot in state["slots"]
        for attempt in slot["attempts"]
        if attempt["finished_at"] is not None
    }
    if (
        Counter(dispatch_events) != Counter({lease: 1 for lease in known_leases})
        or Counter(finish_events) != Counter({lease: 1 for lease in finished_leases})
    ):
        raise SchedulerError("event history differs from attempt lineage")
    reconciled_slots = Counter(
        (
            slot["terminal"]["at"],
            slot["terminal"]["reason"],
            slot["terminal"]["evidence_digest"],
        )
        for slot in state["slots"]
        if slot["status"] == "unstarted"
    )
    reconciled_events: Counter[tuple[str, str, str]] = Counter()
    deferral_anchors: dict[str, tuple[int, dict]] = {}
    for event_index, event in enumerate(state["events"]):
        if event["type"] in {"dispatch", "attempt_finished"}:
            linked = attempts_by_lease.get(event["lease_id"])
            if linked is None:
                raise SchedulerError("attempt event references an unknown lease")
            slot, attempt = linked
            if event["slot_id"] != slot["slot_id"]:
                raise SchedulerError("attempt event references the wrong slot")
            if event["type"] == "dispatch":
                details = event["details"]
                if set(details) != {
                    "planned_order",
                    "actual_order",
                    "wait_duration_ms",
                    "deferral_ids",
                }:
                    raise SchedulerError(
                        "dispatch event fields differ from the ledger contract"
                    )
                deferral_ids = details["deferral_ids"]
                if (
                    not isinstance(deferral_ids, list)
                    or len(deferral_ids) != len(set(deferral_ids))
                ):
                    raise SchedulerError("dispatch deferral identities are invalid")
                for deferral_id in deferral_ids:
                    linked_deferral = deferrals_by_id.get(deferral_id)
                    if linked_deferral is None:
                        raise SchedulerError("dispatch references an unknown deferral")
                    if linked_deferral[1]["at"] != event["at"]:
                        raise SchedulerError(
                            "dispatch references a deferral from another time"
                        )
                    if deferral_id in deferral_anchors:
                        raise SchedulerError("quota deferral has multiple decision anchors")
                    deferral_anchors[deferral_id] = (event_index, event)
                deferrals = [
                    item
                    for item in slot["deferrals"]
                    if item["attempt"] == attempt["attempt"]
                ]
                if any(
                    _timestamp(item["at"]) > _timestamp(attempt["started_at"])
                    for item in deferrals
                ):
                    raise SchedulerError("dispatch precedes its recorded deferral")
                wait_duration_ms = max(
                    (
                        int(
                            (
                                _timestamp(attempt["started_at"])
                                - _timestamp(item["at"])
                            ).total_seconds()
                            * 1000
                        )
                        for item in deferrals
                    ),
                    default=0,
                )
                expected_event = {
                    "type": "dispatch",
                    "at": attempt["started_at"],
                    "slot_id": slot["slot_id"],
                    "lease_id": attempt["lease_id"],
                    "details": {
                        "planned_order": slot["planned_order"],
                        "actual_order": slot["actual_order"],
                        "wait_duration_ms": wait_duration_ms,
                        "deferral_ids": deferral_ids,
                    },
                }
            else:
                retry = (
                    attempt["outcome"] == "infrastructure_failed"
                    and attempt["error_code"]
                    in freeze["limits"]["retry_policy"]["retryable_error_codes"]
                    and attempt["attempt"]
                    < freeze["limits"]["retry_policy"]["max_attempts"]
                )
                expected_event = {
                    "type": "attempt_finished",
                    "at": attempt["finished_at"],
                    "slot_id": slot["slot_id"],
                    "lease_id": attempt["lease_id"],
                    "details": {
                        "outcome": attempt["outcome"],
                        "error_code": attempt["error_code"],
                        "retry": retry,
                    },
                }
            if event != expected_event:
                raise SchedulerError("attempt event evidence differs from its lease")
        elif event["type"] == "reconcile":
            details = event["details"]
            if set(details) != {"reason", "count", "evidence_digest"}:
                raise SchedulerError("reconcile event fields differ from the ledger contract")
            if type(details["count"]) is not int or details["count"] < 0:
                raise SchedulerError("reconcile event count is invalid")
            _require_digest(details["evidence_digest"], "reconciliation evidence")
            if event["slot_id"] is not None or event["lease_id"] is not None:
                raise SchedulerError("reconcile event must not reference a lease")
            if details["count"]:
                reconciled_events[
                    (event["at"], details["reason"], details["evidence_digest"])
                ] += details["count"]
        elif event["type"] == "wait":
            details = event["details"]
            if set(details) != {
                "deferral_ids",
                "reasons",
                "recovery_times",
                "next_recovery_at",
            }:
                raise SchedulerError("wait event fields differ from the ledger contract")
            deferral_ids = details["deferral_ids"]
            if (
                not isinstance(deferral_ids, list)
                or not deferral_ids
                or len(deferral_ids) != len(set(deferral_ids))
            ):
                raise SchedulerError("wait event deferral identities are invalid")
            try:
                linked_deferrals = [deferrals_by_id[item][1] for item in deferral_ids]
            except (KeyError, TypeError) as exc:
                raise SchedulerError("wait event references an unknown deferral") from exc
            if any(item["at"] != event["at"] for item in linked_deferrals):
                raise SchedulerError("wait event references a deferral from another time")
            for deferral_id in deferral_ids:
                if deferral_id in deferral_anchors:
                    raise SchedulerError("quota deferral has multiple decision anchors")
                deferral_anchors[deferral_id] = (event_index, event)
            reasons = [
                reason
                for deferral in linked_deferrals
                for reason in deferral["reasons"]
            ]
            recovery_times = sorted(
                {
                    reason["recovery_at"]
                    for reason in reasons
                    if reason["recovery_at"] is not None
                }
            )
            expected_details = {
                "deferral_ids": deferral_ids,
                "reasons": reasons,
                "recovery_times": recovery_times,
                "next_recovery_at": recovery_times[0] if recovery_times else None,
            }
            if (
                event["slot_id"] is not None
                or event["lease_id"] is not None
                or details != expected_details
            ):
                raise SchedulerError("wait event evidence differs from its deferrals")
    if set(deferral_anchors) != set(deferrals_by_id):
        raise SchedulerError("quota deferral lacks its decision anchor")
    dispatch_positions = {
        event["lease_id"]: index
        for index, event in enumerate(state["events"])
        if event["type"] == "dispatch"
    }
    finish_positions = {
        event["lease_id"]: index
        for index, event in enumerate(state["events"])
        if event["type"] == "attempt_finished"
    }
    account_configs = _accounts(freeze)
    for deferral_id, (slot, deferral) in deferrals_by_id.items():
        anchor_index, anchor = deferral_anchors[deferral_id]
        next_order_at_decision = 1 + len(
            {
                event["slot_id"]
                for event in state["events"][:anchor_index]
                if event["type"] == "dispatch"
            }
        )
        if deferral["decision_id"] != _decision_id(
            state,
            event_number=anchor_index + 1,
            at=anchor["at"],
            next_actual_order=next_order_at_decision,
        ):
            raise SchedulerError("quota deferral has the wrong decision identity")
        prior_attempts = [
            attempt
            for attempt in slot["attempts"]
            if dispatch_positions[attempt["lease_id"]] < anchor_index
        ]
        if deferral["attempt"] != len(prior_attempts) + 1:
            raise SchedulerError("quota deferral does not target the pending attempt")
        if prior_attempts:
            prior = prior_attempts[-1]
            prior_finish = finish_positions.get(prior["lease_id"])
            retry_policy = freeze["limits"]["retry_policy"]
            if (
                prior_finish is None
                or prior_finish >= anchor_index
                or prior["outcome"] != "infrastructure_failed"
                or prior["error_code"] not in retry_policy["retryable_error_codes"]
                or len(prior_attempts) >= retry_policy["max_attempts"]
            ):
                raise SchedulerError("quota deferral targets a slot that was not pending")
        observations = _observation_map(deferral["quota_observations"])
        active_attempts = [
            attempt
            for candidate in state["slots"]
            for attempt in candidate["attempts"]
            if dispatch_positions[attempt["lease_id"]] < anchor_index
            and (
                attempt["lease_id"] not in finish_positions
                or finish_positions[attempt["lease_id"]] >= anchor_index
            )
        ]
        active_by_account: dict[str, int] = {}
        for attempt in active_attempts:
            for account_id in attempt["account_reservations"]:
                active_by_account[account_id] = active_by_account.get(account_id, 0) + 1
        demand = account_reservation_demand(
            freeze,
            slot["arm_id"],
            remaining_attempts=freeze["limits"]["attempts"]
            - deferral["attempt"]
            + 1,
        )
        expected_reasons = []
        for account_id, amount in demand.items():
            account = account_configs[account_id]
            if active_by_account.get(account_id, 0) >= account["max_parallel_workflows"]:
                expected_reasons.append(
                    {
                        "account_id": account_id,
                        "reason": "account_parallelism_exhausted",
                        "recovery_at": None,
                    }
                )
                continue
            observation = observations.get(account_id)
            committed = 0
            if observation is not None:
                baseline = _timestamp(observation["observed_at"])
                for candidate in state["slots"]:
                    for attempt in candidate["attempts"]:
                        dispatch_position = dispatch_positions[attempt["lease_id"]]
                        if dispatch_position >= anchor_index:
                            continue
                        finished = finish_positions.get(attempt["lease_id"])
                        if finished is None or finished >= anchor_index:
                            amounts = attempt["account_reservations"]
                        elif _timestamp(attempt["finished_at"]) >= baseline:
                            amounts = attempt["account_consumption"]
                        else:
                            continue
                        committed += amounts.get(account_id, 0)
            if account_id == _claude_account(freeze):
                committed = 0  # Conserved epoch journal already includes leases.
            eligible, reason, recovery = _account_eligibility(
                account=account,
                observation=observation,
                required=amount,
                already_reserved=committed,
                now=_timestamp(anchor["at"]),
            )
            if not eligible:
                expected_reasons.append(
                    {
                        "account_id": account_id,
                        "reason": reason,
                        "recovery_at": recovery,
                    }
                )
        if len(active_attempts) >= freeze["limits"]["local_compute"]["concurrency"]:
            expected_reasons.append(
                {
                    "account_id": "local-compute",
                    "reason": "local_compute_parallelism_exhausted",
                    "recovery_at": None,
                }
            )
        if deferral["reasons"] != expected_reasons:
            raise SchedulerError("quota deferral reasons differ from retained evidence")
    if reconciled_events != reconciled_slots:
        raise SchedulerError("reconcile event history differs from unstarted slots")
    owner_managed_capacity = _owner_managed_capacity(freeze)
    expected_observations = (Counter() if owner_managed_capacity else Counter(
        (attempt["lease_id"], account_id)
        for slot in state["slots"]
        for attempt in slot["attempts"]
        for account_id in attempt["account_reservations"]
    ))
    actual_observations = Counter(
        (observation["used_for_lease"], observation["account_id"])
        for observation in state["quota_observations"]
    )
    if actual_observations != expected_observations:
        raise SchedulerError("quota observation history differs from reservations")
    for observation in state["quota_observations"]:
        if observation["used_for_lease"] not in known_leases:
            raise SchedulerError("quota observation references an unknown lease")
    event_times = [_timestamp(event["at"]) for event in state["events"]]
    if event_times != sorted(event_times):
        raise SchedulerError("scheduler event history is not chronological")
    if _timestamp(state["updated_at"]) < _timestamp(state["created_at"]):
        raise SchedulerError("scheduler update precedes state creation")
    if event_times and _timestamp(state["updated_at"]) != event_times[-1]:
        raise SchedulerError("updated timestamp differs from the last event")
    if freeze.get("numerical_policy") and not owner_managed_capacity:
        _validate_claude_capacity(state, freeze)
    assert_safe_for_persistence(state)


def _validate_claude_capacity(state, freeze):
    account = _claude_account(freeze)
    observations, charges = {}, {}
    try:
        accounting = claude_capacity.replay(state["claude_capacity"])
        prefix = freeze["numerical_policy"]["claude_qualification_ledger"]["events"]
        events = state["claude_capacity"]["events"]
        if events[:len(prefix)] != prefix or any(
                e['type'] == 'correct_reset_offset'
                or (e["type"] == "charge" and e["kind"] == "qualification") for e in events[len(prefix):]):
            raise ValueError("Claude qualification consumption differs from the frozen journal")
        for snapshot in accounting["snapshots"]:
            event, observation = snapshot["event"], snapshot["observation"]
            observations[observation["evidence_digest"]] = {"account_id": account, **observation}
            expected_active = sorted(
                attempt["lease_id"] for slot in state["slots"] for attempt in slot["attempts"]
                if account in attempt["account_reservations"]
                and attempt["lease_id"] in snapshot["charges"]
                and (attempt["finished_at"] is None
                     or _timestamp(attempt["finished_at"]) > _timestamp(event["at"])))
            if sorted(event["active_leases"]) != expected_active:
                raise ValueError("Claude reset omitted an active reservation")
        for event in events:
            if event["type"] == "charge" and event["kind"] == "attempt":
                charges[event["id"]] = event
        expected = {
            attempt["lease_id"]: {"type": "charge", "at": attempt["started_at"],
                                 "id": attempt["lease_id"], "kind": "attempt",
                                 "units": attempt["account_reservations"][account],
                                 "evidence_digest": digest(freeze["numerical_policy"])}
            for slot in state["slots"] for attempt in slot["attempts"]
            if account in attempt["account_reservations"]}
        if charges != expected:
            raise ValueError("Claude consumption differs from scheduler attempts")
        retained = [dict(o) for o in state["quota_observations"] if o["account_id"] == account]
        retained.extend(dict(o) for slot in state["slots"] for d in slot["deferrals"]
                        for o in d["quota_observations"] if o["account_id"] == account)
        for observation in retained:
            observation.pop("used_for_lease", None)
            if observations.get(observation["evidence_digest"]) != observation:
                raise ValueError("Claude quota observation differs from conserved epochs")
    except (ValueError, KeyError, TypeError) as error:
        raise SchedulerError(f"invalid Claude accounting: {error}") from error


def _current_block(state: Mapping[str, Any]) -> list[dict]:
    for slot in state["slots"]:
        if slot["status"] not in {"terminal", "unstarted"}:
            identity = (slot["task_id"], slot["repetition"])
            return [
                candidate
                for candidate in state["slots"]
                if (candidate["task_id"], candidate["repetition"]) == identity
            ]
    return []


def _observation_map(observations: list[Mapping[str, Any]]) -> dict[str, Mapping[str, Any]]:
    result = {}
    for observation in observations:
        if set(observation) != OBSERVATION_FIELDS:
            raise SchedulerError("quota observation fields differ from the safe contract")
        account_id = observation["account_id"]
        if not isinstance(account_id, str) or not account_id:
            raise SchedulerError("quota observation account identity is invalid")
        if account_id in result:
            raise SchedulerError("duplicate quota observation for actual account")
        observed_at = _timestamp(observation["observed_at"])
        valid_until = _timestamp(observation["valid_until"])
        if observed_at > valid_until:
            raise SchedulerError("quota observation expires before it was observed")
        for field in ("recovery_at", "weekly_recovery_at"):
            if observation[field] is not None:
                _timestamp(observation[field])
        for field in (
            "remaining_workflows",
            "weekly_remaining_workflows",
            "conservative_capacity_workflows",
        ):
            value = observation[field]
            if value is not None and (type(value) is not int or value < 0):
                raise SchedulerError(f"quota observation {field} is invalid")
        external = observation["external_usage_workflows"]
        if type(external) is not int or external < 0:
            raise SchedulerError("quota observation external usage is invalid")
        _require_digest(observation["evidence_digest"], "quota evidence")
        result[account_id] = observation
    return result


def _active_by_account(state: Mapping[str, Any]) -> dict[str, int]:
    active: dict[str, int] = {}
    for reservation in state["reservations"]:
        for account_id in reservation["accounts"]:
            active[account_id] = active.get(account_id, 0) + 1
    return active


def _committed_after(
    state: Mapping[str, Any], account_id: str, observed_at: str | datetime
) -> int:
    """Capacity committed after an observation, conserved across restart."""
    baseline = _timestamp(observed_at)
    committed = 0
    for slot in state["slots"]:
        for attempt in slot["attempts"]:
            if attempt["finished_at"] is None:
                amounts = attempt["account_reservations"]
            elif _timestamp(attempt["finished_at"]) >= baseline:
                amounts = attempt["account_consumption"]
            else:
                continue
            committed += amounts.get(account_id, 0)
    return committed


def _account_eligibility(
    *,
    account: Mapping[str, Any],
    observation: Mapping[str, Any] | None,
    required: int,
    already_reserved: int,
    now: datetime,
) -> tuple[bool, str, str | None]:
    policy = account["missing_telemetry_policy"]
    if observation is None:
        return False, "missing_quota_telemetry", None
    if observation.get("evidence_digest") is None:
        return False, "quota_observation_lacks_evidence", None
    observed_at = _timestamp(observation["observed_at"])
    valid_until = _timestamp(observation["valid_until"])
    rolling_recovery_at = observation.get("recovery_at")
    weekly_recovery_at = observation.get("weekly_recovery_at")
    if not observed_at <= now <= valid_until:
        recovery_times = [value for value in (rolling_recovery_at, weekly_recovery_at) if value]
        recovery = max(map(_format_timestamp, recovery_times), default=None)
        return False, "stale_quota_telemetry", recovery
    remaining = observation.get("remaining_workflows")
    weekly = observation.get("weekly_remaining_workflows")
    if remaining is None or weekly is None:
        if policy == "pause":
            recovery_times = [value for value in (rolling_recovery_at, weekly_recovery_at) if value]
            recovery = max(map(_format_timestamp, recovery_times), default=None)
            return False, "incomplete_quota_telemetry", recovery
        conservative = observation.get("conservative_capacity_workflows")
        if conservative is None:
            recovery_times = [value for value in (rolling_recovery_at, weekly_recovery_at) if value]
            recovery = max(map(_format_timestamp, recovery_times), default=None)
            return False, "missing_conservative_capacity", recovery
        if remaining is None:
            remaining = conservative
        if weekly is None:
            weekly = conservative
    capacity = max(
        0,
        min(remaining, weekly) - observation.get("external_usage_workflows", 0),
    )
    external_reserve = math.ceil(
        capacity * account["external_usage_reserve_percentage"] / 100
    )
    safety = account["reserved_workflows"]
    available = capacity - external_reserve - safety - already_reserved
    if available < required:
        recovery_times = []
        if remaining <= weekly and rolling_recovery_at:
            recovery_times.append(rolling_recovery_at)
        if weekly <= remaining and weekly_recovery_at:
            recovery_times.append(weekly_recovery_at)
        recovery = max(map(_format_timestamp, recovery_times), default=None)
        return False, "insufficient_whole_workflow_headroom", recovery
    return True, "eligible", None


def dispatch_next(
    state: dict,
    freeze: Mapping[str, Any],
    *,
    observations: list[Mapping[str, Any]] | None,
    claude_reading: Mapping[str, Any] | None = None,
    now: str | datetime,
    allow_fixture: bool = False,
    stage_a_freeze: Mapping[str, Any] | None = None,
    trusted_stage_a_freeze_digest: str | None = None,
    host_admission=None,
    stage_a_admission=None,
    trusted_stage_a_disposition_digest: str | None = None,
    trusted_stage_a_outcome_seal_digest: str | None = None,
) -> dict | None:
    """Reserve and return the earliest eligible slot in the current block.

    ``None`` means the cohort is complete.  A blocked block raises SchedulerError
    after recording why each pending slot was deferred; callers can inspect the
    event's recovery times and wait without counting that time as execution.
    """
    validate_state(
        state,
        freeze,
        stage_a_freeze=stage_a_freeze,
        trusted_stage_a_freeze_digest=trusted_stage_a_freeze_digest,
        trusted_stage_a_disposition_digest=trusted_stage_a_disposition_digest,
        trusted_stage_a_outcome_seal_digest=trusted_stage_a_outcome_seal_digest,
    )
    _require_mutation_authorized(freeze, allow_fixture=allow_fixture)
    if freeze.get('purpose') == 'freeze':
        from agent_harness_evals.host_profile import HostAdmission
        if not isinstance(host_admission, HostAdmission):
            raise SchedulerError('production dispatch requires an admitted target host profile')
        try:
            host_admission.check(state, freeze)
            if freeze.get("schema_version") == "staged-multilang-benchmark/5":
                from agent_harness_evals.stage_a_numerical import StageAAdmission
                if not isinstance(stage_a_admission, StageAAdmission):
                    raise ValueError("owner-approved seven-arm numerical freeze and fresh admission required")

