def validate_frozen_slot_plan(plan: Mapping[str, Any]) -> None:
    """Validate the exact pre-dispatch slot-to-task/arm mapping."""
    errors = sorted(
        _validator("task-outcome-slot-plan-v1.schema.json").iter_errors(plan),
        key=lambda error: list(error.path),
    )
    if errors:
        raise ValueError(f"frozen slot plan violates schema: {errors[0].message}")
    slot_ids = [slot["slot_id"] for slot in plan["slots"]]
    if any(str(uuid.UUID(slot_id)) != slot_id for slot_id in slot_ids):
        raise ValueError("frozen slot plan requires canonical UUID slot identities")
    if len(slot_ids) != len(set(slot_ids)):
        raise ValueError("frozen slot plan contains duplicate slot identities")


def outcome_contract_identity(frozen_slot_plan: Mapping[str, Any]) -> dict[str, Any]:
    """Return the exact identity a future run contract must freeze pre-dispatch."""
    validate_frozen_slot_plan(frozen_slot_plan)
    artifacts = [
        _SCHEMAS / "trial-result.schema.json",
        _SCHEMAS / "task-outcome-evidence-v1.schema.json",
        _SCHEMAS / "task-outcome-slot-plan-v1.schema.json",
        _SCHEMAS / "task-outcome-v2.schema.json",
        _SCHEMAS / "trial-result-v2.schema.json",
        _SCHEMAS / "task-outcome-seal-v2.schema.json",
        Path(__file__).resolve(),
    ]
    identities = [
        {
            "path": str(path.relative_to(_ROOT)),
            "sha256": _file_sha256(path),
        }
        for path in artifacts
    ]
    identity = {
        "contract_id": CONTRACT_ID,
        "primary_policy": PRIMARY_POLICY,
        "timeout_policy": TIMEOUT_POLICY,
        "combined_cause_precedence": PRECEDENCE_POLICY,
        "feedback_policy": FEEDBACK_POLICY,
        "slot_plan_sha256": _canonical_sha256(frozen_slot_plan),
        "artifacts": identities,
    }
    return {**identity, "identity_sha256": _canonical_sha256(identity)}


def validate_frozen_outcome_contract(
    frozen: Mapping[str, Any], frozen_slot_plan: Mapping[str, Any]
) -> None:
    """Reject execution, resume, or sealing after any outcome-contract drift."""
    if dict(frozen) != outcome_contract_identity(frozen_slot_plan):
        raise ValueError("frozen task outcome contract identity changed")


def build_outcome_report(
    records: Sequence[Mapping[str, Any]],
    *,
    frozen_slot_plan: Mapping[str, Any],
    artifact_root: Path,
) -> dict[str, Any]:
    """Aggregate independent dimensions; never substitute verifier for primary."""
    validate_frozen_slot_plan(frozen_slot_plan)
    for record in records:
        interpretation = record.get("interpretation")
        if (
            isinstance(interpretation, Mapping)
            and interpretation.get("mode") == "offline_reinterpretation"
        ):
            raise ValueError(
                "offline reinterpretations cannot enter a prospective outcome report"
            )
        validate_normalized_benchmark_result_v2(record, artifact_root=artifact_root)
    planned = {slot["slot_id"]: slot for slot in frozen_slot_plan["slots"]}
    slot_ids = [record["slot_id"] for record in records]
    trial_ids = [record["trial_id"] for record in records]
    result_ids = [record["result_id"] for record in records]
    if len(slot_ids) != len(set(slot_ids)):
        raise ValueError("outcome report requires one unique terminal record per slot")
    if len(trial_ids) != len(set(trial_ids)):
        raise ValueError("outcome report contains duplicate attempt identities")
    if len(result_ids) != len(set(result_ids)):
        raise ValueError("outcome report contains duplicate result identities")
    if set(slot_ids) != set(planned):
        raise ValueError("terminal outcome records do not match the frozen slot plan")
    for record in records:
        slot = planned[record["slot_id"]]
        expected = {
            key: slot[key] for key in ("arm_id", "manifest_digest", "task")
        }
        if any(record[key] != value for key, value in expected.items()):
            raise ValueError("terminal record identity does not match its frozen slot")
        if record["attempt"] > slot["max_attempts"]:
            raise ValueError("terminal record exceeds its frozen attempt limit")
    dimensions = [record["outcome_dimensions"] for record in records]
    primary = [item["primary_task_outcome"] for item in dimensions]
    scored = [item for item in primary if item["score"] is not None]
    dispositions = ("automated", "human")
    return {
        "schema_version": REPORT_SCHEMA_VERSION,
        "scheduled_slots": len(records),
        "primary": {
            "statuses": dict(sorted(Counter(item["status"] for item in primary).items())),
            "denominators": dict(sorted(Counter(item["denominator"] for item in primary).items())),
            "scored_slots": len(scored),
            "score_sum": sum(item["score"] for item in scored),
        },
        "verifier_results": dict(
            sorted(Counter(item["verifier_result"]["status"] for item in dimensions).items())
        ),
        "terminal_reasons": dict(
            sorted(Counter(item["termination"]["reason"] for item in dimensions).items())
        ),
        "delivery_statuses": dict(
            sorted(Counter(item["delivery"]["status"] for item in dimensions).items())
        ),
        "dispositions": {
            kind: dict(
                sorted(Counter(item["dispositions"][kind]["status"] for item in dimensions).items())
            )
            for kind in dispositions
        },
    }


def build_outcome_seal(
    *,
    stage_id: str,
    sealed_at: str,
    records: Sequence[Mapping[str, Any]],
    frozen_slot_plan: Mapping[str, Any],
    frozen_outcome_contract: Mapping[str, Any],
    artifact_root: Path,
) -> dict[str, Any]:
    """Seal exact contract identity, records, and the dimension-preserving report."""
    validate_frozen_outcome_contract(frozen_outcome_contract, frozen_slot_plan)
    if stage_id != frozen_slot_plan["stage_id"]:
        raise ValueError("outcome seal stage does not match frozen slot plan")
    report = build_outcome_report(
        records, frozen_slot_plan=frozen_slot_plan, artifact_root=artifact_root
    )
    seal = {
        "schema_version": SEAL_SCHEMA_VERSION,
        "stage_id": stage_id,
        "sealed_at": sealed_at,
        "outcome_contract": dict(frozen_outcome_contract),
        "slot_plan_sha256": _canonical_sha256(frozen_slot_plan),
        "records_sha256": _canonical_sha256(records),
        "report": report,
    }
    errors = sorted(
        _validator("task-outcome-seal-v2.schema.json").iter_errors(seal),
        key=lambda error: list(error.path),
    )
    if errors:
        raise ValueError(f"outcome seal violates v2 schema: {errors[0].message}")
    return seal


def validate_outcome_seal(
    seal: Mapping[str, Any],
    *,
    frozen_slot_plan: Mapping[str, Any],
    records: Sequence[Mapping[str, Any]],
    artifact_root: Path,
) -> None:
    """Recompute every semantic seal field from its retained plan and records."""
    errors = sorted(
        _validator("task-outcome-seal-v2.schema.json").iter_errors(seal),
        key=lambda error: list(error.path),
    )
    if errors:
        raise ValueError(f"outcome seal violates v2 schema: {errors[0].message}")
    expected = build_outcome_seal(
        stage_id=seal["stage_id"],
        sealed_at=seal["sealed_at"],
        records=records,
        frozen_slot_plan=frozen_slot_plan,
        frozen_outcome_contract=seal["outcome_contract"],
        artifact_root=artifact_root,
    )
    if dict(seal) != expected:
        raise ValueError("outcome seal contradicts its retained plan or records")


@cache
def _validator(name: str) -> Draft202012Validator:
    schemas = [json.loads(path.read_text()) for path in _SCHEMAS.glob("*.schema.json")]
    registry = Registry().with_resources(
        (schema["$id"], Resource.from_contents(schema))
        for schema in schemas
        if "$id" in schema
    )
    schema = next(
        schema
        for schema in schemas
        if "$id" in schema and Path(schema["$id"]).name == name
    )
    return Draft202012Validator(
        schema, registry=registry, format_checker=FormatChecker()
    )

